<?php $pageTitle='Customer Enquiries';require '../includes/admin-header.php';$pdo=db();if(($_GET['action']??'')==='close'&&!empty($_GET['id'])){$pdo->prepare("UPDATE contact_messages SET status='closed' WHERE id=?")->execute([(int)$_GET['id']]);flash('success','Enquiry closed.');go('admin/enquiries.php');}$messages=$pdo->query('SELECT * FROM contact_messages ORDER BY created_at DESC')->fetchAll();?><div class="card table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Date</th><th>Customer</th><th>Contact</th><th>Message</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($messages as $m):?><tr><td><?=e($m['created_at'])?></td><td><b><?=e($m['name'])?></b><br><small><?=e($m['subject']?:'General enquiry')?></small></td><td><?=e($m['email'])?><br><?=e($m['phone'])?></td><td><?=nl2br(e($m['message']))?></td><td><?=e($m['status'])?></td><td><?php if($m['status']==='new'):?><a class="btn btn-sm btn-outline-dark" href="enquiries.php?action=close&id=<?=$m['id']?>">Close</a><?php endif?></td></tr><?php endforeach?><?php if(!$messages):?><tr><td colspan="6" class="text-center text-muted py-4">No customer enquiries yet.</td></tr><?php endif?></tbody></table></div><?php require '../includes/admin-footer.php';?>
